import{_ as a,a as s,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第一册：英语初阶 · 单元 3 复习与自测 · 第56–62课","description":"L49–L72 原创练习和答案解析。","frontmatter":{"title":"第一册：英语初阶 · 单元 3 复习与自测 · 第56–62课","description":"L49–L72 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-1/unit-03/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 单元 3 复习与自测","summary":"L49–L72 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 单元 3 复习与自测 · 第49–55课","link":"/life/english/new-concept/book-1/unit-03/review-part-01"},"next":{"text":"第一册：英语初阶 · 单元 3 复习与自测 · 第63–69课","link":"/life/english/new-concept/book-1/unit-03/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 单元 3 复习与自测 · 第49–55课","link":"/life/english/new-concept/book-1/unit-03/review-part-01"},"next":{"text":"第一册：英语初阶 · 单元 3 复习与自测 · 第63–69课","link":"/life/english/new-concept/book-1/unit-03/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-03/review-part-02.md","filePath":"life/english/new-concept/book-1/unit-03/review-part-02.md"}'),n={name:"life/english/new-concept/book-1/unit-03/review-part-02.md"};function i(l,e,r,h,p,u){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-单元-3-复习与自测-·-第56–62课" tabindex="-1">第一册：英语初阶 · 单元 3 复习与自测 · 第56–62课 <a class="header-anchor" href="#第一册-英语初阶-·-单元-3-复习与自测-·-第56–62课" aria-label="Permalink to &quot;第一册：英语初阶 · 单元 3 复习与自测 · 第56–62课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/unit-03/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-1/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-1/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-1/unit-03/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-56-·-一般现在时的习惯动作" tabindex="-1">Lesson 56 · 一般现在时的习惯动作 <a class="header-anchor" href="#lesson-56-·-一般现在时的习惯动作" aria-label="Permalink to &quot;Lesson 56 · 一般现在时的习惯动作 {#lesson-56-·-一般现在时的习惯动作}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We usually cook dinner together.</p><h3 id="练习-1-7" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-7" aria-label="Permalink to &quot;练习 1 {#练习-1-7}&quot;">​</a></h3><p>选择 at/in：___ half past seven.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> at</p><p><strong>解析：</strong> 按本课规则判断：一般现在时描述习惯、规律和相对稳定状态。谈家庭成员时要逐个检查主语：parents 用 go，father 用 goes。时间表达可用 at seven、in the evening、on Mondays。通常活动不必加 now，now 更容易指向正在进行。every day 是时间短语，everyday 是形容词，修饰日常事物。</p></details><p><strong>表达迁移：</strong> 围绕“介绍一家人的每日作息”写两至三句，再读给同伴听。至少使用一次一般现在时的习惯动作，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We usually cook dinner together. My father leaves home at half past seven.</p><p>We 为复数主语，cook 用原形；usually 放在实义动词前，together 表示一起完成动作。 My father 为第三人称单数，所以用 leaves；home 在 leave home 中表示离开家，at half past seven 表钟点。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-056">回看本课</a></p><h2 id="lesson-57-·-一般现在时与现在进行时" tabindex="-1">Lesson 57 · 一般现在时与现在进行时 <a class="header-anchor" href="#lesson-57-·-一般现在时与现在进行时" aria-label="Permalink to &quot;Lesson 57 · 一般现在时与现在进行时 {#lesson-57-·-一般现在时与现在进行时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I usually cycle to work, but today I am taking the bus.</p><h3 id="练习-1-8" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-8" aria-label="Permalink to &quot;练习 1 {#练习-1-8}&quot;">​</a></h3><p>填动词：I usually ___ (cycle) to work.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> cycle</p><p><strong>解析：</strong> 按本课规则判断：一般现在时说明通常怎样，现在进行时说明现在正在怎样。对比段落可用 usually 与 today/now 建立时间框架。选择时态要看动作意义，而非看到 today 就一律进行时。like、know 等状态动词通常不用进行时表达普通状态。现在进行时既要有 be，也要有动词 ing。</p></details><p><strong>表达迁移：</strong> 围绕“对比平时安排和今天的变化”写两至三句，再读给同伴听。至少使用一次一般现在时与现在进行时，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I usually cycle to work, but today I am taking the bus. Leo is wearing a suit now.</p><p>Usually cycle 说明惯常出行；but 连接对比，today I am taking the bus 描述今天的临时安排或进行中的出行。 Leo 是单数主语，is wearing 描述此刻穿着；wear 表穿着状态，a suit 为宾语，now 给出当前时间。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-057">回看本课</a></p><h2 id="lesson-58-·-一般现在时与现在进行时" tabindex="-1">Lesson 58 · 一般现在时与现在进行时 <a class="header-anchor" href="#lesson-58-·-一般现在时与现在进行时" aria-label="Permalink to &quot;Lesson 58 · 一般现在时与现在进行时 {#lesson-58-·-一般现在时与现在进行时}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Leo is wearing a suit now.</p><h3 id="练习-1-9" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-9" aria-label="Permalink to &quot;练习 1 {#练习-1-9}&quot;">​</a></h3><p>填 be：Leo ___ wearing a suit now.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：一般现在时说明通常怎样，现在进行时说明现在正在怎样。对比段落可用 usually 与 today/now 建立时间框架。选择时态要看动作意义，而非看到 today 就一律进行时。like、know 等状态动词通常不用进行时表达普通状态。现在进行时既要有 be，也要有动词 ing。</p></details><p><strong>表达迁移：</strong> 围绕“对比平时安排和今天的变化”写两至三句，再读给同伴听。至少使用一次一般现在时与现在进行时，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Leo is wearing a suit now. I usually cycle to work, but today I am taking the bus.</p><p>Leo 是单数主语，is wearing 描述此刻穿着；wear 表穿着状态，a suit 为宾语，now 给出当前时间。 Usually cycle 说明惯常出行；but 连接对比，today I am taking the bus 描述今天的临时安排或进行中的出行。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-058">回看本课</a></p><h2 id="lesson-59-·-可数和不可数名词的数量" tabindex="-1">Lesson 59 · 可数和不可数名词的数量 <a class="header-anchor" href="#lesson-59-·-可数和不可数名词的数量" aria-label="Permalink to &quot;Lesson 59 · 可数和不可数名词的数量 {#lesson-59-·-可数和不可数名词的数量}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We need five envelopes and some writing paper.</p><h3 id="练习-1-10" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-10" aria-label="Permalink to &quot;练习 1 {#练习-1-10}&quot;">​</a></h3><p>选择 much/many：How ___ envelopes?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> many</p><p><strong>解析：</strong> 按本课规则判断：可数名词用 many、a few 或具体数词，通常有复数形式；不可数名词用 much、a little 或量词。some 可用于两者。have 作拥有的实义动词时，否定可用 don&#39;t have。购物清单中 a kilo of apples 的数量核心是 kilo，复数时写 two kilos of apples。不要把中文数量词直接省略。</p></details><p><strong>表达迁移：</strong> 围绕“核对购物清单并表达数量”写两至三句，再读给同伴听。至少使用一次可数和不可数名词的数量，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We need five envelopes and some writing paper. How much flour do you need?</p><p>Need 的宾语由 five envelopes 和 some writing paper 并列组成：前者可数复数，后者不可数。 How much flour 是疑问宾语，flour 不可数；do 放在主语 you 之前，need 用原形。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-059">回看本课</a></p><h2 id="lesson-60-·-可数和不可数名词的数量" tabindex="-1">Lesson 60 · 可数和不可数名词的数量 <a class="header-anchor" href="#lesson-60-·-可数和不可数名词的数量" aria-label="Permalink to &quot;Lesson 60 · 可数和不可数名词的数量 {#lesson-60-·-可数和不可数名词的数量}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> How much flour do you need?</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>选择 much/many：How ___ flour?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> much</p><p><strong>解析：</strong> 按本课规则判断：可数名词用 many、a few 或具体数词，通常有复数形式；不可数名词用 much、a little 或量词。some 可用于两者。have 作拥有的实义动词时，否定可用 don&#39;t have。购物清单中 a kilo of apples 的数量核心是 kilo，复数时写 two kilos of apples。不要把中文数量词直接省略。</p></details><p><strong>表达迁移：</strong> 围绕“核对购物清单并表达数量”写两至三句，再读给同伴听。至少使用一次可数和不可数名词的数量，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>How much flour do you need? We need five envelopes and some writing paper.</p><p>How much flour 是疑问宾语，flour 不可数；do 放在主语 you 之前，need 用原形。 Need 的宾语由 five envelopes 和 some writing paper 并列组成：前者可数复数，后者不可数。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-060">回看本课</a></p><h2 id="lesson-61-·-have-表身体状况与-must" tabindex="-1">Lesson 61 · have 表身体状况与 must <a class="header-anchor" href="#lesson-61-·-have-表身体状况与-must" aria-label="Permalink to &quot;Lesson 61 · have 表身体状况与 must {#lesson-61-·-have-表身体状况与-must}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Mina has a headache today.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>填 have 的形式：Mina ___ a headache.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> has</p><p><strong>解析：</strong> 按本课规则判断：have 可表达某些身体状况，如 have a headache；be 与形容词搭配，如 be tired。must + 原形可表达强烈要求，但本页只是语言练习，不提供诊断或治疗建议。询问状况可用 What is the matter with ...?，with 后用宾格。第三人称肯定 have 变 has，疑问用 does ... have。</p></details><p><strong>表达迁移：</strong> 围绕“描述身体不适并理解必要事项”写两至三句，再读给同伴听。至少使用一次have 表身体状况与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Mina has a headache today. What is the matter with him?</p><p>Mina 是第三人称单数，have 变 has；a headache 是表示身体状况的名词短语，today 表时间。 What is the matter 构成询问状况的固定问句；with him 指明对象，him 是介词后的宾格。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-061">回看本课</a></p><h2 id="lesson-62-·-have-表身体状况与-must" tabindex="-1">Lesson 62 · have 表身体状况与 must <a class="header-anchor" href="#lesson-62-·-have-表身体状况与-must" aria-label="Permalink to &quot;Lesson 62 · have 表身体状况与 must {#lesson-62-·-have-表身体状况与-must}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> What is the matter with him?</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>选择 he/him：What is the matter with ___?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> him</p><p><strong>解析：</strong> 按本课规则判断：have 可表达某些身体状况，如 have a headache；be 与形容词搭配，如 be tired。must + 原形可表达强烈要求，但本页只是语言练习，不提供诊断或治疗建议。询问状况可用 What is the matter with ...?，with 后用宾格。第三人称肯定 have 变 has，疑问用 does ... have。</p></details><p><strong>表达迁移：</strong> 围绕“描述身体不适并理解必要事项”写两至三句，再读给同伴听。至少使用一次have 表身体状况与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>What is the matter with him? Mina has a headache today.</p><p>What is the matter 构成询问状况的固定问句；with him 指明对象，him 是介词后的宾格。 Mina 是第三人称单数，have 变 has；a headache 是表示身体状况的名词短语，today 表时间。</p></details><p><a href="/life/english/new-concept/book-1/unit-03/lesson-062">回看本课</a></p>',60)])])}const d=a(n,[["render",i]]);export{m as __pageData,d as default};
